func LowStockThreshold(warehouse string) int {
	if thresholds, ok := loadThresholds(); ok {
		if threshold, configured := thresholds[warehouse]; configured {
			return threshold
		}
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取仓库根下的 config/thresholds.json。
//
// ok 为 false 表示没有可用的配置，调用方应回退到默认值。
func loadThresholds() (map[string]int, bool) {
	path, ok := configPath()
	if !ok {
		return nil, false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	if thresholds == nil {
		return nil, false // JSON null 不是对象
	}
	return thresholds, true
}

// configPath 从当前工作目录往上找到含 go.mod 的仓库根，返回其中的配置路径。
func configPath() (string, bool) {
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, thresholdConfig), true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}
