	if err := os.WriteFile(filepath.Join(root, "go.mod"), []byte("module test\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if setup != nil {
		setup(root)
	}
	return root
}

// writeThresholds 在仓库根下写 config/thresholds.json。
func writeThresholds(t *testing.T, root, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Join(root, "config"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "config", "thresholds.json"), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestLowStockThresholdReadsConfiguredWarehouse(t *testing.T) {
	root := makeRepoRoot(t, func(root string) { writeThresholds(t, root, `{"xian": 9}`) })
	t.Chdir(root)

	if got := LowStockThreshold("xian"); got != 9 {
		t.Fatalf("LowStockThreshold(\"xian\") = %d, 期望配置值 9", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

