func TestLowStockThresholdFallsBackWithoutUsableConfig(t *testing.T) {
	cases := []struct {
		name  string
		setup func(t *testing.T, root string)
	}{
		{"文件不存在", nil},
		{"内容不是 JSON", func(t *testing.T, root string) { writeThresholds(t, root, "not json") }},
		{"JSON 不是对象", func(t *testing.T, root string) { writeThresholds(t, root, "[1,2,3]") }},
		{"JSON 是 null", func(t *testing.T, root string) { writeThresholds(t, root, "null") }},
		{"读不出来", func(t *testing.T, root string) {
			if err := os.MkdirAll(filepath.Join(root, "config", "thresholds.json"), 0o755); err != nil {
				t.Fatal(err)
			}
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			root := makeRepoRoot(t, func(root string) {
				if tc.setup != nil {
					tc.setup(t, root)
				}
			})
			sub := filepath.Join(root, "inventory")
			if err := os.MkdirAll(sub, 0o755); err != nil {
				t.Fatal(err)
			}
			t.Chdir(sub)

			if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
				t.Fatalf("LowStockThreshold(\"xian\") = %d, 期望回退默认值 %d", got, DefaultLowStockThreshold)
			}
		})
	}
}
